const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;

    var P = { x: 340, y: 350 };
    var dx = 0.9120, dy = 0.4104;
    var A = { x: P.x - 240 * dx, y: P.y - 240 * dy };
    var B = { x: P.x + 120 * dx, y: P.y + 120 * dy };
    var A1 = { x: P.x - 290 * dx, y: P.y - 290 * dy };
    var B1 = { x: P.x + 155 * dx, y: P.y + 155 * dy };

    var off = { x: 16, y: -35 };
    var Aoff = { x: A.x + off.x, y: A.y + off.y };
    var Poff = { x: P.x + off.x, y: P.y + off.y };
    var Boff = { x: B.x + off.x, y: B.y + off.y };

    var n6 = { x: 2.46, y: -5.47 };

    var grassCmds = [];
    for (var gx = 60; gx <= 840; gx += 40) {
      grassCmds = grassCmds.concat(visualSdk.polyline([[gx, 430], [gx - 9, 446]]));
    }

    var fulcrumCmds = visualSdk.polyline([[P.x, P.y], [300, 430], [380, 430]]);
    fulcrumCmds.push('Z');

    var rockCmds = visualSdk.polyline([[B.x, B.y], [462, 300], [560, 292], [588, 399.25]]);
    rockCmds.push('Z');

    var texCmds = [];
    texCmds = texCmds.concat(visualSdk.polyline([[480, 340], [510, 352], [500, 378]]));
    texCmds = texCmds.concat(visualSdk.polyline([[520, 318], [552, 330]]));
    texCmds = texCmds.concat(visualSdk.polyline([[540, 370], [568, 358]]));

    var tickCmds = [];
    var tickPoints = [Aoff, Poff, Boff];
    for (var i = 0; i < tickPoints.length; i++) {
      var tp = tickPoints[i];
      tickCmds = tickCmds.concat(visualSdk.polyline([
        [tp.x - n6.x, tp.y - n6.y],
        [tp.x + n6.x, tp.y + n6.y]
      ]));
    }

    var leadCmds = [];
    leadCmds = leadCmds.concat(visualSdk.polyline([[A.x, A.y], [Aoff.x, Aoff.y]]));
    leadCmds = leadCmds.concat(visualSdk.polyline([[P.x, P.y], [Poff.x, Poff.y]]));
    leadCmds = leadCmds.concat(visualSdk.polyline([[B.x, B.y], [Boff.x, Boff.y]]));

    var leverCmds = visualSdk.axis({ x0: A1.x, y0: A1.y, x1: B1.x, y1: B1.y });
    var leverHiCmds = visualSdk.axis({
      x0: A1.x + 2.0, y0: A1.y - 4.6,
      x1: B1.x + 2.0, y1: B1.y - 4.6
    });

    var dimDCmds = visualSdk.axis({ x0: Aoff.x, y0: Aoff.y, x1: Poff.x, y1: Poff.y });
    var dimRCmds = visualSdk.axis({ x0: Poff.x, y0: Poff.y, x1: Boff.x, y1: Boff.y });

    var arrowCmds = visualSdk.arrow(121, 158, 121, 230, { headSize: 18 });
    var contactCmds = visualSdk.circle(B.x, B.y, 5);

    var groundCmds = visualSdk.axis({ x0: 40, y0: 430, x1: 860, y1: 430 });
    var shadowCmds = visualSdk.axis({ x0: 460, y0: 424, x1: 590, y1: 424 });

    var paths = [
      { id: 'shadow', commands: shadowCmds },
      { id: 'ground', commands: groundCmds },
      { id: 'grass', commands: grassCmds },
      { id: 'fulcrum', commands: fulcrumCmds },
      { id: 'lever', commands: leverCmds },
      { id: 'leverHi', commands: leverHiCmds },
      { id: 'rock', commands: rockCmds },
      { id: 'rockTex', commands: texCmds },
      { id: 'dimD', commands: dimDCmds },
      { id: 'dimR', commands: dimRCmds },
      { id: 'ticks', commands: tickCmds },
      { id: 'leaders', commands: leadCmds },
      { id: 'arrow', commands: arrowCmds },
      { id: 'contact', commands: contactCmds }
    ];

    var root = {
      type: 'group',
      children: [
        { type: 'path', pathId: 'shadow', fill: '#c7cfc0', stroke: { width: 8 } },
        { type: 'path', pathId: 'ground', fill: '#6b7a5a', stroke: { width: 4 } },
        { type: 'path', pathId: 'grass', fill: '#8a9a72', stroke: { width: 2 } },
        { type: 'path', pathId: 'fulcrum', fill: '#3b4a5a', stroke: { width: 3 } },
        { type: 'path', pathId: 'lever', fill: '#b07a45', stroke: { width: 16 } },
        { type: 'path', pathId: 'leverHi', fill: '#e3b47c', stroke: { width: 4 } },
        { type: 'path', pathId: 'rock', fill: '#8b98a6', stroke: { width: 3 } },
        { type: 'path', pathId: 'rockTex', fill: '#6f7c8a', stroke: { width: 2 } },
        { type: 'path', pathId: 'leaders', fill: '#9aa7b4', stroke: { width: 1.5 } },
        { type: 'path', pathId: 'dimD', fill: '#2f6fb0', stroke: { width: 2.5 } },
        { type: 'path', pathId: 'dimR', fill: '#d9822b', stroke: { width: 2.5 } },
        { type: 'path', pathId: 'ticks', fill: '#5a6b7a', stroke: { width: 2 } },
        { type: 'path', pathId: 'arrow', fill: '#d9534f', stroke: { width: 2 } },
        { type: 'path', pathId: 'contact', fill: '#d9822b', stroke: { width: 2 } },
        { type: 'label', contentId: 'c0', anchor: { x: 340, y: 452 }, hAlign: 'center', vAlign: 'top', color: '#2f3b4a' },
        { type: 'label', contentId: 'c1', anchor: { x: 246.6, y: 251.8 }, hAlign: 'center', vAlign: 'bottom', color: '#2f6fb0' },
        { type: 'label', contentId: 'c2', anchor: { x: 410.7, y: 325.6 }, hAlign: 'center', vAlign: 'bottom', color: '#d9822b' }
      ]
    };

    return {
      schemaVersion: 1,
      sceneId: 'lever-stone',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: root
    };
  }
};
